cat > src/orchestration/tools/registry-typed-runtime.test.ts <<'EOF'
import {ToolRegistry} from './registry.js';

// spec: specs/hal-engine-tool-input-validation/spec.md#13
it('rejects a numeric weather location through the runtime validator', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {
      name: 'weather',
      description: 'Weather lookup',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    },
    async () => 'forecast'
  );

  const response = await registry.execute('weather', {location: 123});

  expect(response).toEqual({result: expect.stringMatching(/location.*type.*string/)});
});
EOF
